import json

bedrock = boto3.client('bedrock-runtime')

def stream_completion(text):
    model_id = 'amazon.titan-tg1-large'
    body = {
        'inputText': text,
        'textGenerationConfig': {
            'maxTokenCount': 2048,
            'temperature': 0.5,
            'topP': 0.9
        }
    }
    response = bedrock.invoke_model(
        body=json.dumps(body),
        modelId=model_id,
        accept='application/json',
        contentType='application/json',
        stream=True
    )
    for event in response.get('body'):
        chunk = json.loads(event)
        yield chunk.get('results')[0].get('outputText')

from typing import Dict

def normalize_request(input_text: str, max_tokens: int = 2048, temperature: float = 0.5, top_p: float = 0.9) -> Dict:
    return {
        'inputText': input_text,
        'textGenerationConfig': {
            'maxTokenCount': max_tokens,
            'temperature': temperature,
            'topP': top_p
        }
    }

def parse_response(response: Dict) -> str:
    return response.get('results')[0].get('outputText')

